  method: 'PATCH',
  url: 'http://localhost:3001/users/M1ty1gR8B3',
  body: {
    id: 'M1ty1gR8B3',
    firstName: 'Pavel',
    lastName: 'QA',
    email: 'pavel@test.com',
    phoneNumber: '123-456-7890',
    defaultPrivacyLevel: 'private'
  }
}).then(response => {
  expect(response.status).to.eq(204);
});
